import{_ as s,C as i,c as l,o as u,ah as a,j as e,G as r,a as n}from"./chunks/framework.C2OYgiIb.js";const k=JSON.parse('{"title":"Manufacturing Orders","description":"","frontmatter":{},"headers":[],"relativePath":"master/manufacturing/operations/manufacturing-orders.md","filePath":"master/manufacturing/operations/manufacturing-orders.md","lastUpdated":1779101762000}'),d={name:"master/manufacturing/operations/manufacturing-orders.md"};function p(c,t,g,h,m,f){const o=i("ImagePopup");return u(),l("div",null,[t[11]||(t[11]=a('<h1 id="manufacturing-orders" tabindex="-1">Manufacturing Orders <a class="header-anchor" href="#manufacturing-orders" aria-label="Permalink to &quot;Manufacturing Orders&quot;">​</a></h1><p>A <strong>Manufacturing Order (MO)</strong> is the primary document that drives production. It tells the system <strong>what to produce</strong>, <strong>how many units</strong>, <strong>from which BoM</strong>, <strong>by when</strong>, and <strong>who is responsible</strong>.<br> Once confirmed, an MO automatically:</p><ul><li>Reserves the required components from stock.</li><li>Generates the underlying <strong>Work Orders</strong> (when Work Orders is enabled).</li><li>Tracks consumption, by-products, and finished output.</li><li>Updates inventory upon completion.</li></ul><p><strong>Use Case:</strong><br> Create a Manufacturing Order every time you need to launch production — whether on customer demand, to replenish stock, or for an internal project.</p><blockquote><p><strong>In simple words:</strong> A Manufacturing Order is like a &quot;production work ticket&quot;. It says <em>&quot;Make 10 chairs, using this recipe, starting on this date.&quot;</em> The system then handles the rest — reserving wood, screws, and fabric, and telling each operator what to do.</p></blockquote><h2 id="before-you-begin-—-setup-checklist" tabindex="-1">Before You Begin — Setup Checklist <a class="header-anchor" href="#before-you-begin-—-setup-checklist" aria-label="Permalink to &quot;Before You Begin — Setup Checklist&quot;">​</a></h2><p>A Manufacturing Order is the <strong>last step</strong> of the manufacturing process. Before you can create one, a few building blocks must already exist in the system. Complete them in this order:</p><table tabindex="0"><thead><tr><th>Step</th><th>What to set up</th><th>Where</th><th>Guide</th></tr></thead><tbody><tr><td>1</td><td>The <strong>finished product</strong> you want to manufacture</td><td><code>Manufacturing → Products → Products</code></td><td><a href="./../products/products.html">Products</a></td></tr><tr><td>2</td><td>The <strong>raw materials / components</strong> used to build it</td><td><code>Manufacturing → Products → Products</code></td><td><a href="./../products/products.html">Products</a></td></tr><tr><td>3</td><td>The <strong>Work Centers</strong> where production happens <em>(optional — only if Work Orders is enabled)</em></td><td><code>Manufacturing → Configurations → Work Centers</code></td><td><a href="./../configurations/work-centers.html">Work Centers</a></td></tr><tr><td>4</td><td>The <strong>Bill of Material (BoM)</strong> — the recipe linking the product to its components</td><td><code>Manufacturing → Products → Bills of Materials</code></td><td><a href="./../products/bills-of-material.html">Bills of Material</a></td></tr><tr><td>5</td><td>The <strong>Operations</strong> — the shop-floor steps inside the BoM <em>(optional — only if Work Orders is enabled)</em></td><td><code>Manufacturing → Configurations → Operations</code></td><td><a href="./../configurations/operations.html">Operations</a></td></tr><tr><td>6</td><td>The <strong>Manufacturing Order</strong> itself</td><td><code>Manufacturing → Operations → Manufacturing Orders</code></td><td>This page</td></tr></tbody></table><blockquote><p>You also need the right capabilities switched on. Review the <a href="./../settings.html">Manufacturing Settings</a> page to enable <strong>Work Orders</strong>, <strong>Work Order Dependencies</strong>, or <strong>Byproducts</strong> depending on how detailed your production process is.</p></blockquote><h3 id="enabling-the-3-step-manufacturing-route" tabindex="-1">Enabling the 3-Step Manufacturing Route <a class="header-anchor" href="#enabling-the-3-step-manufacturing-route" aria-label="Permalink to &quot;Enabling the 3-Step Manufacturing Route&quot;">​</a></h3><p>By default, manufacturing happens in a single step (components go straight into production and finished goods go straight to stock). If you want a more controlled flow — <strong>pick the components → manufacture → store the finished product</strong> — you must enable the <strong>3-step manufacturing route</strong> on your warehouse.</p>',11)),e("ol",null,[e("li",null,[t[0]||(t[0]=e("p",null,[e("strong",null,"Turn on multi-step routes."),n(" Navigate to "),e("strong",null,[e("code",null,"Inventory → Settings → Manage Warehouses")]),n(" and enable "),e("strong",null,"Multi Steps Routes"),n(", then click "),e("strong",null,"Save Changes"),n(". See the "),e("a",{href:"./../../inventories/settings.html#manage-warehouses"},"Inventory Settings"),n(" guide.")],-1)),r(o,{src:"/images1/manufacturing/mo_enable_multi_step_routes.png",alt:"Enable Multi Steps Routes"})]),e("li",null,[t[1]||(t[1]=e("p",null,[e("strong",null,"Edit the warehouse."),n(" Navigate to "),e("strong",null,[e("code",null,"Inventory → Configurations → Warehouse Management")]),n(", open the warehouse you produce in, and click "),e("strong",null,"Edit"),n(". See the "),e("a",{href:"./../../inventories/configurations/warehouse-management.html"},"Warehouse Management"),n(" guide.")],-1)),r(o,{src:"/images1/manufacturing/mo_warehouse_edit.png",alt:"Edit Warehouse"})]),e("li",null,[t[2]||(t[2]=e("p",null,[e("strong",null,"Select the 3-step manufacturing option."),n(" In the warehouse form, find the "),e("strong",null,"Manufacturing"),n(" setting and choose "),e("strong",null,"Manufacture in 3 Steps (Pick components → Manufacture → Store)"),n(".")],-1)),r(o,{src:"/images1/manufacturing/mo_three_step_manufacturing.png",alt:"Enable 3 Step Manufacturing"})]),t[3]||(t[3]=e("li",null,[e("p",null,[e("strong",null,"Save it."),n(" Click "),e("strong",null,"Save"),n(". The system automatically creates the extra locations and operation types (e.g. "),e("em",null,"Pick Components"),n(", "),e("em",null,"Manufacturing"),n(", "),e("em",null,"Store Finished Product"),n(") needed for the 3-step flow.")])],-1))]),t[12]||(t[12]=e("blockquote",null,[e("p",null,[e("strong",null,"Tip:"),n(" Choose "),e("strong",null,"1 Step"),n(" for simple production and "),e("strong",null,"3 Steps"),n(" when you need to formally pick materials before production and put finished goods away after — useful for larger warehouses and audit trails.")])],-1)),t[13]||(t[13]=e("h2",{id:"steps-to-create-a-new-manufacturing-order",tabindex:"-1"},[n("Steps to Create a New Manufacturing Order "),e("a",{class:"header-anchor",href:"#steps-to-create-a-new-manufacturing-order","aria-label":'Permalink to "Steps to Create a New Manufacturing Order"'},"​")],-1)),e("ol",null,[e("li",null,[t[4]||(t[4]=e("p",null,[n("Navigate to "),e("strong",null,[e("code",null,"Manufacturing → Operations → Manufacturing Orders")]),n(" as shown below:")],-1)),r(o,{src:"/images1/manufacturing/mo_navigation.png",alt:"Manufacturing Orders Navigation"})]),e("li",null,[t[5]||(t[5]=a('<p>Fill in the following details:</p><h4 id="general-section" tabindex="-1">General Section <a class="header-anchor" href="#general-section" aria-label="Permalink to &quot;General Section&quot;">​</a></h4><ul><li><strong><em>Product:</em></strong> The finished product to manufacture. It must already exist in <a href="./../products/products.html">Products</a>.</li><li><strong><em>Quantity:</em></strong> Number of units to produce.</li><li><strong><em>UoM:</em></strong> Unit of measure for the quantity (auto-filled from the product).</li><li><strong><em>Bill of Material:</em></strong> Choose which <a href="./../products/bills-of-material.html">Bill of Material</a> (recipe) to use. If the product has only one BoM, it is selected automatically.</li><li><strong><em>Scheduled Date:</em></strong> Planned <strong>start date</strong> of production. The system uses this date along with the BoM lead time to plan operations.</li><li><strong><em>Scheduled End:</em></strong> Expected <strong>completion date</strong> based on operation durations.</li><li><strong><em>Responsible:</em></strong> User accountable for this manufacturing order.</li><li><strong><em>To Produce:</em></strong> Image preview of the finished product (read-only).</li></ul>',3)),r(o,{src:"/images1/manufacturing/mo_general_section.png",alt:"MO General Section"})]),t[6]||(t[6]=e("li",null,[e("p",null,[n("Configure the "),e("strong",null,"tabs"),n(" below the general section.")])],-1))]),t[14]||(t[14]=a('<h3 id="components-tab" tabindex="-1">Components Tab <a class="header-anchor" href="#components-tab" aria-label="Permalink to &quot;Components Tab&quot;">​</a></h3><p>Lists every raw material required to produce the planned quantity. Populated automatically from the selected BoM and refreshed whenever the quantity changes.</p><p>For each line:</p><ul><li><strong><em>Product:</em></strong> The component.</li><li><strong><em>From:</em></strong> Source location (where the component will be picked from).</li><li><strong><em>To Consume:</em></strong> Quantity required for this MO. If the available stock is below this number, a tooltip indicates <strong>Insufficient quantity available</strong>.</li><li><strong><em>Quantity:</em></strong> Actual quantity consumed (filled in when production starts).</li><li><strong><em>UoM:</em></strong> Unit of measure.</li><li><strong><em>Forecast:</em></strong> Projected on-hand level after this MO consumes the component.</li></ul><p>You can click <strong>Add a line</strong> to add an unplanned component on the fly.</p>',5)),r(o,{src:"/images1/manufacturing/mo_components_tab.png",alt:"MO Components Tab"}),t[15]||(t[15]=a('<blockquote><p>When the manufacturing process is still being built, you will see the note <strong>&quot;Components will be generated as the manufacturing process is built.&quot;</strong> Confirm the BoM/quantity first to populate this tab.</p></blockquote><h3 id="work-orders-tab" tabindex="-1">Work Orders Tab <a class="header-anchor" href="#work-orders-tab" aria-label="Permalink to &quot;Work Orders Tab&quot;">​</a></h3><p>Visible when <strong>Work Orders</strong> is enabled. Lists every <a href="./work-orders.html">Work Order</a> generated from the BoM&#39;s <a href="./../configurations/operations.html">Operations</a>.</p><p>Columns:</p><ul><li><strong><em>Operation:</em></strong> The step name (e.g. <em>Cutting</em>).</li><li><strong><em>Work Center:</em></strong> Where the step runs.</li><li><strong><em>Product:</em></strong> Item being produced.</li><li><strong><em>Quantity Remaining / Produced:</em></strong> Live counters updated as operators record progress.</li><li><strong><em>Start / End:</em></strong> Scheduled or actual times.</li><li><strong><em>Expected Duration / Real Duration:</em></strong> Compare planned vs. tracked time.</li><li><strong><em>Status:</em></strong> Workflow state (Ready, In Progress, Pending, Done…).</li><li><strong><em>Lot/Serial:</em></strong> Lot or serial assigned at this step.</li></ul>',5)),r(o,{src:"/images1/manufacturing/mo_work_orders_tab.png",alt:"MO Work Orders Tab"}),t[16]||(t[16]=a('<h3 id="miscellaneous-tab" tabindex="-1">Miscellaneous Tab <a class="header-anchor" href="#miscellaneous-tab" aria-label="Permalink to &quot;Miscellaneous Tab&quot;">​</a></h3><ul><li><strong><em>Operation Type:</em></strong> Warehouse operation that records the production (e.g. <code>Primary Warehouse: Manufacturing</code>).</li><li><strong><em>Source:</em></strong> Origin document — for example a sales order, replenishment, or another MO — that triggered this production.</li><li><strong><em>Finished Products Location:</em></strong> Stock location where finished units will be deposited (e.g. <code>Primary/Stock</code>).</li><li><strong><em>Company:</em></strong> Company that owns the MO.</li></ul>',2)),r(o,{src:"/images1/manufacturing/mo_miscellaneous_tab.png",alt:"MO Miscellaneous Tab"}),t[17]||(t[17]=a('<ol start="5"><li><p><strong>Action Buttons:</strong></p><ul><li><strong>Create</strong> – Save the MO as a Draft.</li><li><strong>Create &amp; Create Another</strong> – Save and open another blank MO.</li><li><strong>Cancel</strong> – Discard.</li></ul></li></ol><h2 id="manufacturing-order-workflow" tabindex="-1">Manufacturing Order Workflow <a class="header-anchor" href="#manufacturing-order-workflow" aria-label="Permalink to &quot;Manufacturing Order Workflow&quot;">​</a></h2><p>After creation, you are redirected to the <strong>MO View Page</strong> which exposes the full workflow.</p>',3)),r(o,{src:"/images1/manufacturing/mo_view_page.png",alt:"Manufacturing Order View Page"}),t[18]||(t[18]=a('<p>The MO progresses through the following states:</p><p><code>Draft</code> → <code>Confirmed</code> → <code>Planned</code> → <code>In Progress</code> → <code>To Close</code> → <code>Done</code></p><p>(with optional <code>Cancelled</code> from any state before completion.)</p><blockquote><p><strong>Behind the scenes — stock transfers.</strong> Every MO is backed by inventory <strong>transfers</strong> that physically move stock between locations. In a <strong>3-step route</strong> the system creates a <strong>Pick Components</strong> transfer (raw materials → production area) and, after production, a <strong>Store Finished Product</strong> transfer (finished goods → stock). In a <strong>1-step route</strong> both moves are posted automatically when you click <strong>Produce All</strong>. You can review and validate every transfer from the <strong>Manage Transfers</strong> tab.</p></blockquote><h3 id="confirm" tabindex="-1">Confirm <a class="header-anchor" href="#confirm" aria-label="Permalink to &quot;Confirm&quot;">​</a></h3><p>Click <strong>Confirm</strong> to validate the MO. The system reserves the required components, generates the work orders, and — in a 3-step route — creates the <strong>Pick Components</strong> transfer so the raw materials can be moved to the production area. The state changes to <strong>Confirmed</strong>.</p>',6)),r(o,{src:"/images1/manufacturing/mo_confirm_action.png",alt:"Confirm Manufacturing Order"}),t[19]||(t[19]=a('<h3 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h3><p>Click <strong>Plan</strong> to schedule each <a href="./work-orders.html">Work Order</a> on its <a href="./../configurations/work-centers.html">Work Center</a> based on capacity and dependencies. State becomes <strong>Planned</strong>.</p><h3 id="unplan" tabindex="-1">Unplan <a class="header-anchor" href="#unplan" aria-label="Permalink to &quot;Unplan&quot;">​</a></h3><p>Click <strong>Unplan</strong> to release the scheduled slots — useful if dates or priorities change. The MO returns to <strong>Confirmed</strong>.</p><h3 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;Start&quot;">​</a></h3><p>Click <strong>Start</strong> to mark production as actively in progress. The first <a href="./work-orders.html">Work Order</a> becomes available to operators. State becomes <strong>In Progress</strong>.</p><h3 id="validate-the-component-pick-transfer" tabindex="-1">Validate the Component Pick Transfer <a class="header-anchor" href="#validate-the-component-pick-transfer" aria-label="Permalink to &quot;Validate the Component Pick Transfer&quot;">​</a></h3><p>In a <strong>3-step route</strong>, the raw materials do not leave their storage location until the <strong>Pick Components</strong> transfer is validated.</p><ol><li>Open the <strong>Transfers</strong> tab and edit the <strong>Pick Components</strong> transfer.</li><li>Check the picked quantities, then click <strong>Validate</strong>.</li><li>The components move from <code>Stock</code> to the production location, and the <strong>on-hand quantity of each raw material is reduced</strong> accordingly.</li></ol>',9)),r(o,{src:"/images1/manufacturing/mo_transfers_tab.png",alt:"Manufacturing Order Transfers"}),t[20]||(t[20]=a('<blockquote><p><strong>Note — 1-step route:</strong> If your warehouse uses the 1-step route there is no separate pick transfer — component stock is consumed directly when you click <strong>Produce All</strong>.</p></blockquote><h3 id="produce-all" tabindex="-1">Produce All <a class="header-anchor" href="#produce-all" aria-label="Permalink to &quot;Produce All&quot;">​</a></h3><p>Click <strong>Produce All</strong> to validate the MO and post the finished quantity. The system consumes the components recorded on the <strong>Components</strong> tab and, in a <strong>3-step route</strong>, generates the <strong>Store Finished Product</strong> transfer for the newly produced units. State becomes <strong>Done</strong>.</p><p>If consumption or produced quantities differ from the plan, the system shows a <strong>Consumption Warning</strong> or <strong>Produced is different than expected</strong> dialog so you can:</p><ul><li>Confirm with the current quantities, <strong>or</strong></li><li>Click <strong>Set Quantities and Confirm</strong> to keep the planned values.</li></ul>',5)),r(o,{src:"/images1/manufacturing/mo_produce_all_action.png",alt:"Produce All Action"}),r(o,{src:"/images1/manufacturing/mo_consumption_warning.png",alt:"Consumption Warning Modal"}),t[21]||(t[21]=a('<blockquote><p><strong>Note — Over-consumption warning:</strong> If an operator records <strong>more of a component than the quantity defined in the BoM</strong>, the system raises a <strong>Consumption Warning</strong> when you validate. The dialog lists each over- or under-consumed component so you can either accept the actual quantities or click <strong>Set Quantities and Confirm</strong> to revert to the planned BoM values. The same check applies to output — producing more or fewer units than planned triggers the <strong>&quot;Produced is different than expected&quot;</strong> dialog.</p></blockquote><h3 id="store-the-finished-product" tabindex="-1">Store the Finished Product <a class="header-anchor" href="#store-the-finished-product" aria-label="Permalink to &quot;Store the Finished Product&quot;">​</a></h3><p>In a <strong>3-step route</strong>, the finished units are not added to sellable stock until the <strong>Store Finished Product</strong> transfer is validated.</p><ol><li>Open the <strong>Transfers</strong> tab and edit the <strong>Store Finished Product</strong> transfer.</li><li>Verify the quantity and destination location, then click <strong>Validate</strong>.</li><li>The finished goods move into <code>Stock</code> and become available for sale or further production.</li></ol>',4)),r(o,{src:"/images1/manufacturing/mo_store_finished_product_action.png",alt:"Store Finished Product Action"}),t[22]||(t[22]=a('<blockquote><p>In a <strong>1-step route</strong> the finished goods are posted to stock immediately on <strong>Produce All</strong> — no separate transfer is needed.</p></blockquote><h3 id="cancel" tabindex="-1">Cancel <a class="header-anchor" href="#cancel" aria-label="Permalink to &quot;Cancel&quot;">​</a></h3><p>Click <strong>Cancel</strong> at any point before completion to abort the MO. Reserved components are released. State becomes <strong>Cancelled</strong>.</p><h3 id="other-page-actions" tabindex="-1">Other Page Actions <a class="header-anchor" href="#other-page-actions" aria-label="Permalink to &quot;Other Page Actions&quot;">​</a></h3>',4)),e("ul",null,[e("li",null,[t[7]||(t[7]=e("p",null,[e("strong",null,"Overview:"),n(" Open the MO overview report with a full hierarchical breakdown of components, costs, and durations.")],-1)),r(o,{src:"/images1/manufacturing/mo_overview_page.png",alt:"Manufacturing Order Overview"})]),e("li",null,[t[8]||(t[8]=e("p",null,[e("strong",null,"Transfers:"),n(" Open the "),e("strong",null,"Manage Transfers"),n(" sub-tab to view every stock move triggered by this MO (component picks, finished product put-away, scraps).")],-1)),r(o,{src:"/images1/manufacturing/mo_transfers_tab1.png",alt:"Manufacturing Order Transfers"})]),e("li",null,[t[9]||(t[9]=e("p",null,[e("strong",null,"Print MO / Print Labels:"),n(" Generate a printable order sheet or product labels for shop-floor use.")],-1)),r(o,{src:"/images1/manufacturing/mo_print_actions.png",alt:"Print Manufacturing Order"})]),t[10]||(t[10]=e("li",null,[e("p",null,[e("strong",null,"Edit / Delete:"),n(" Modify or remove the MO (only in draft / cancelled states).")])],-1))]),t[23]||(t[23]=a('<h2 id="list-view-—-filters-groups-reservation-state" tabindex="-1">List View — Filters, Groups &amp; Reservation State <a class="header-anchor" href="#list-view-—-filters-groups-reservation-state" aria-label="Permalink to &quot;List View — Filters, Groups &amp; Reservation State&quot;">​</a></h2><p>The <strong>Manufacturing Orders</strong> list shows: <strong>Reference</strong>, <strong>Product</strong>, <strong>Bill of Material</strong>, <strong>Quantity</strong>, <strong>Scheduled Date</strong>, <strong>Responsible</strong>, <strong>State</strong>, and <strong>Consumption Efficiency</strong>.</p><p>You can:</p><ul><li><strong>Group by:</strong> State, Product, BoM, Responsible, or Scheduled Date.</li><li><strong>Filter by:</strong> State, reservation state, product, responsible, or scheduled date range.</li></ul><p>A color-coded badge on each row indicates the <strong>Reservation State</strong> (e.g. <em>Confirmed</em>, <em>Waiting Another Operation</em>, <em>Ready</em>) so you can spot blocked orders instantly.</p>',5)),r(o,{src:"/images1/manufacturing/mo_list_view.png",alt:"Manufacturing Order List View"}),t[24]||(t[24]=a(`<h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>A Manufacturing Order is the <strong>central hub</strong> of production — it ties together the <a href="./../products/bills-of-material.html">Bill of Material</a>, components, <a href="./work-orders.html">Work Orders</a>, by-products, and transfers.<br> Use the workflow buttons (<strong>Confirm → Plan → Start → Produce All</strong>) to drive it through its lifecycle, and rely on the overview and transfers tabs to verify the full picture before marking it complete.</p><h2 id="complete-manufacturing-flow-—-start-to-end" tabindex="-1">Complete Manufacturing Flow — Start to End <a class="header-anchor" href="#complete-manufacturing-flow-—-start-to-end" aria-label="Permalink to &quot;Complete Manufacturing Flow — Start to End&quot;">​</a></h2><p>The diagram below shows the <strong>full journey</strong>, from the very first setup step to a finished product in stock. Steps <strong>1–5</strong> are one-time setup (do them once, reuse them forever). Steps <strong>6–7</strong> are repeated every time you produce something.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ┌──────────────────────── ONE-TIME SETUP ────────────────────────┐</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  STEP 1                STEP 2                 STEP 3</span></span>
<span class="line"><span>┌─────────────┐      ┌──────────────┐      ┌──────────────┐</span></span>
<span class="line"><span>│  Create the │      │  Create the  │      │   Create     │</span></span>
<span class="line"><span>│  FINISHED   │ ───▶ │ RAW MATERIAL │ ───▶ │ WORK CENTERS │</span></span>
<span class="line"><span>│  PRODUCT    │      │ / COMPONENTS │      │ (where work  │</span></span>
<span class="line"><span>│ to be made  │      │ used to make │      │  is done)    │</span></span>
<span class="line"><span>│             │      │   it         │      │  *optional*  │</span></span>
<span class="line"><span>└─────────────┘      └──────────────┘      └──────────────┘</span></span>
<span class="line"><span>                                                   │</span></span>
<span class="line"><span>                                                   ▼</span></span>
<span class="line"><span>  STEP 6                STEP 5                 STEP 4</span></span>
<span class="line"><span>┌─────────────┐      ┌──────────────┐      ┌──────────────┐</span></span>
<span class="line"><span>│  Create the │      │   Add the    │      │  Create the  │</span></span>
<span class="line"><span>│ MANUFACTURING│ ◀── │  OPERATIONS  │ ◀── │ BILL OF      │</span></span>
<span class="line"><span>│   ORDER     │      │ (shop-floor  │      │ MATERIAL     │</span></span>
<span class="line"><span>│   (MO)      │      │  steps)      │      │ (the recipe) │</span></span>
<span class="line"><span>│             │      │  *optional*  │      │              │</span></span>
<span class="line"><span>└─────────────┘      └──────────────┘      └──────────────┘</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └──────────────────────── PRODUCTION RUN ────────────────────────┐</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  STEP 7 — Run the Manufacturing Order through its workflow:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Draft ─▶ Confirm ─▶ Plan ─▶ Start ─▶ Produce All ─▶ Done</span></span>
<span class="line"><span>            (reserve   (schedule (begin    (finish &amp;       (finished</span></span>
<span class="line"><span>            materials） work     work)     post to stock)   goods in</span></span>
<span class="line"><span>                       orders)                              inventory)</span></span></code></pre></div><h3 id="step-by-step-explanation" tabindex="-1">Step-by-step explanation <a class="header-anchor" href="#step-by-step-explanation" aria-label="Permalink to &quot;Step-by-step explanation&quot;">​</a></h3><ol><li><strong>Create the finished product</strong> — Add the item you want to manufacture (e.g. <em>Wooden Chair</em>). See <a href="./../products/products.html">Products</a>.</li><li><strong>Create the raw materials / components</strong> — Add every part needed to build it (e.g. <em>Wood Plank</em>, <em>Screws</em>, <em>Fabric</em>). These are also created as products. See <a href="./../products/products.html">Products</a>.</li><li><strong>Create the Work Centers</strong> <em>(optional)</em> — Set up the machines or stations where production happens (e.g. <em>Cutting Station</em>, <em>Assembly Line</em>). Needed only if <strong>Work Orders</strong> is enabled. See <a href="./../configurations/work-centers.html">Work Centers</a>.</li><li><strong>Create the Bill of Material (BoM)</strong> — Build the &quot;recipe&quot; that links the finished product to its components and quantities. See <a href="./../products/bills-of-material.html">Bills of Material</a>.</li><li><strong>Add the Operations</strong> <em>(optional)</em> — Inside the BoM, define the shop-floor steps (e.g. <em>Cut → Assemble → Polish</em>) and assign each to a work center. Needed only if <strong>Work Orders</strong> is enabled. See <a href="./../configurations/operations.html">Operations</a>.</li><li><strong>Create the Manufacturing Order (MO)</strong> — Choose the product, quantity, BoM, and dates. The MO pulls in components and work orders automatically.</li><li><strong>Run the MO workflow</strong> — Drive the order through <strong>Confirm → Plan → Start → Produce All</strong>. When it reaches <strong>Done</strong>, the finished product is added to stock and the components are consumed.</li></ol><blockquote><p><strong>Quick mental model:</strong> <em>Product + Components = the &quot;what&quot;</em>, <em>BoM + Operations + Work Centers = the &quot;how&quot;</em>, and the <em>Manufacturing Order = the &quot;do it now&quot;</em>.</p></blockquote>`,8))])}const _=s(d,[["render",p]]);export{k as __pageData,_ as default};
